style.css:
@-moz-document domain("roblox.com") {
/* Grund-Einstellungen */
  html, body {
    height: 100%;
    margin: 0;
    position: relative;
  }

  /* Fixierter Hintergrund über die gesamte Seite */
  html body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background-image: url(https://i.postimg.cc/tJ2x5LRM/wp7276404.jpg); /* Funktionierendes Testbild */
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    filter: brightness(0.95) saturate(1.1);
    z-index: -9999;
    pointer-events: none;
  }

  /* Rosa Overlay, leicht transparent, wenig Blur */
  html body::after {
    content: "";
    position: fixed;
    inset: 0;
    background: rgba(255, 200, 230, 0.15); /* dezenter rosa Ton */
    backdrop-filter: blur(0px); /* kein zusätzliches Verwischen des Hintergrunds */
    z-index: -9998;
    pointer-events: none;
  }

  /* Glasige Panels */
  .container, #container, .main, .content, .section-content, .profile-page, .navbar, .game-home-page, .scroller {
    background: rgba(255, 255, 255, 0.18) !important;
    backdrop-filter: blur(8px) !important;
    border-radius: 14px !important;
  }

  /* Schwarzer Text für Lesbarkeit */
  body, p, span, div, h1, h2, h3, a {
    color: #222 !important;
  }

  /* Links rosa */
  a {
    color: #ff76b5 !important;
    transition: color 0.3s ease;
  }
  a:hover {
    color: #ff9ecb !important;
  }

  /* Linke Sidebar pastellrosa */
  [class*="nav"], [class*="sidebar"], [class*="menu"], [class*="Navigation"] {
    background: rgba(255, 182, 193, 0.7) !important;
    backdrop-filter: blur(8px) !important;
    border-radius: 14px !important;
  }

  /* Sanfte Übergänge für alles */
  * {
    transition: color 0.3s ease, background-color 0.3s ease, border 0.3s ease, transform 0.3s ease, opacity 0.3s ease;
  }
}
